<?php declare( strict_types=1 ); namespace Inc\Repositories\WPDBRepositories; use Inc\DTO\Exam\ExamOperationKeyDTO; use Inc\Enums\Settings\TableName; class ExamOperationKeyRepository { private \wpdb $wpdb; private string $table; public function __construct( ?\wpdb $wpdb = null ) { $this->wpdb = $wpdb ?? $GLOBALS['wpdb']; $this->table = TableName::ExamOperationKeys->prefixed(); } public function insert( array $data ): int { $this->wpdb->insert( $this->table, $data ); return (int) $this->wpdb->insert_id; } public function find( int $id ): ?ExamOperationKeyDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE id = %d", $this->table, $id ), ARRAY_A ); return $row ? ExamOperationKeyDTO::fromArray( $row ) : null; } public function findByKey( string $scope, string $operation, string $requestKey ): ?ExamOperationKeyDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE scope = %s AND operation = %s AND request_key = %s", $this->table, $scope, $operation, $requestKey ), ARRAY_A ); return $row ? ExamOperationKeyDTO::fromArray( $row ) : null; } public function update( int $id, array $data ): bool { return false !== $this->wpdb->update( $this->table, $data, [ 'id' => $id ] ); } }
